 5→@use 'sass:meta';
 6→
 7→// Note: make sure the following do not emit anything (should only export mixins)
 8→@use './layers.scss' as layers;
 9→@use './global/reset.scss' as reset;
10→@use './global/global.scss' as global;
11→@use './context/theming.scss' as theming;
12→@use './global/accessibility.scss' as accessibility;
13→@use './global/fonts.scss' as fonts;
14→@use '../typography/Prose/Prose.mixins.scss' as prose;
15→
16→
17→//
18→// Emit
19→//
20→
21→@include layers.styles; // Cascade layer ordering: MUST be emitted before anything else
22→
23→@layer reset { @include reset.styles; } // Reset all user agent styling to a minimal/consistent base
24→
25→// User-oriented styling (high layer specificity in order to apply to everything by default). If a component needs
26→// to override these styling (e.g. custom focus outline), then use `!important`.
27→// Note: despite being in a high layer, emitted early so that it is parsed sooner.
28→@layer accessibility { @include accessibility.styles; }
29→
30→// Baklava-specific styling
31→@layer baklava.base { @include global.styles; }
32→@layer baklava.theming { @include theming.styles; }
33→@layer baklava.prose { @include prose.styles; }
34→
35→// Emit fonts last, because vite will inline the font files, and we don't want to block the rest of the styling
36→@layer baklava.base { @include fonts.styles; }
