 55→type ActionIconProps = ComponentProps<typeof IconButton> & {
 56→  /** Optional custom tooltip text, if different from `label`. */
 57→  tooltip?: undefined | ComponentProps<typeof TooltipProvider>['tooltip'],
 58→};
 59→/**
 60→ * An action that is rendered as just an icon.
 61→ */
 62→const ActionIcon = ({ tooltip, ...buttonProps }: ActionIconProps) => {
 63→  return (
 64→    <TooltipProvider compact tooltip={typeof tooltip !== 'undefined' ? tooltip : buttonProps.label}>
 65→      <IconButton
 66→        {...buttonProps}
 67→        className={cx(cl['bk-banner__action'], cl['bk-banner__action--icon'], buttonProps.className)}
 68→        // Prevent clicks from triggering any click handlers on the Banner itself (e.g. to prevent toast dismissal)
 69→        onClick={event => { event.stopPropagation(); buttonProps.onClick?.(event); }}
 70→      />
 71→    </TooltipProvider>
 72→  );
